-- ══════════════════════════════════════════════════════════════════════
-- **«قرب المعلم» في طلب السائق** (قرارُ المالك ٢٠٢٦-١٠-٢١)
-- ══════════════════════════════════════════════════════════════════════
--
-- يرى السائقُ مع العنوان **«حي X · قرب جامع Y (١٢٠ م)»** — فيعرف المكانَ قبل
-- أن يفتح الخريطة.
--
-- **المعالمُ** من OpenStreetMap وOverture وGeoNames (محافظةُ الرقّة، بأسماءٍ
-- عربيّة)، **والمتاجرُ النشطةُ من جدولها مباشرةً** — فكلُّ متجرٍ جديدٍ معلمٌ بلا
-- استيراد.
--
-- **ويُحسب مرّةً عند الإنشاء** (وعند تبدّل نقطة التسليم) فيُحفظ في
-- `orders.near_landmark` — **لا عند كلّ قراءة**. والعنوانُ المحفوظُ لا يُمسّ:
-- السائقُ وحدَه يراه ملصقاً بالعنوان (`orderview.go`).
CREATE TABLE IF NOT EXISTS map_landmarks (
    id     bigserial PRIMARY KEY,
    name   text NOT NULL,
    kind   text NOT NULL,
    point  geography(Point, 4326) NOT NULL,
    source text NOT NULL
);
CREATE INDEX IF NOT EXISTS map_landmarks_point_idx ON map_landmarks USING gist (point);


ALTER TABLE orders ADD COLUMN IF NOT EXISTS near_landmark text;

-- **أقربُ معلمٍ ضمن ٣٠٠ م، والمعروفُ أَوْلى**: الجامعُ والمدرسةُ والمشفى والساحةُ
-- والحديقةُ والمتجرُ تُقاس مسافتُها بستّة أعشارها — فجامعٌ على ١٥٠ م يسبق
-- دكّاناً على ١٢٠ م. **والحيُّ** أقربُ اسمِ حيٍّ ضمن ١٢٠٠ م.
CREATE OR REPLACE FUNCTION orders_near_landmark() RETURNS trigger AS $$
DECLARE
    nb text;
    lm text;
    dm double precision;
BEGIN
    IF NEW.dropoff IS NULL THEN
        NEW.near_landmark := NULL;
        RETURN NEW;
    END IF;
    SELECT l.name INTO nb FROM map_landmarks l
     WHERE l.kind = 'place=neighbourhood' AND ST_DWithin(l.point, NEW.dropoff, 1200)
     ORDER BY ST_Distance(l.point, NEW.dropoff) LIMIT 1;
    SELECT c.name, c.d INTO lm, dm FROM (
        SELECT l.name, ST_Distance(l.point, NEW.dropoff) AS d,
               CASE WHEN l.kind IN ('amenity=place_of_worship', 'amenity=school', 'amenity=hospital',
                                    'amenity=university', 'place=square', 'leisure=park')
                    THEN 0.6 ELSE 1.0 END AS w
          FROM map_landmarks l
         WHERE l.kind <> 'place=neighbourhood' AND ST_DWithin(l.point, NEW.dropoff, 300)
        UNION ALL
        SELECT m.name, ST_Distance(m.location, NEW.dropoff), 0.6
          FROM merchants m
         WHERE m.status = 'active' AND m.location IS NOT NULL
           AND ST_DWithin(m.location, NEW.dropoff, 300)
    ) c ORDER BY c.d * c.w LIMIT 1;
    NEW.near_landmark := NULLIF(concat_ws(' · ',
        CASE WHEN nb IS NULL THEN NULL WHEN nb LIKE 'حي%' THEN nb ELSE 'حي ' || nb END,
        CASE WHEN lm IS NULL THEN NULL
             ELSE 'قرب ' || lm || ' (' || (round(dm / 10) * 10)::int || ' م)' END), '');
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS orders_near_landmark_trg ON orders;
CREATE TRIGGER orders_near_landmark_trg
    BEFORE INSERT OR UPDATE OF dropoff ON orders
    FOR EACH ROW EXECUTE FUNCTION orders_near_landmark();
